const NOIDA_BY_SLUG = new Map();
const NOIDA_BY_ID = new Map();
NOIDA_REGISTRY_PROJECTS.forEach((p) => {
  NOIDA_BY_SLUG.set(p.slug, p);
  NOIDA_BY_ID.set(String(p.id), p);
  const shortSlug = p.slug.replace(/-pid-\d+$/, "");
  if (!NOIDA_BY_SLUG.has(shortSlug)) {
    NOIDA_BY_SLUG.set(shortSlug, p);
  }
});

export const NOIDA_ALL_SLUGS = NOIDA_REGISTRY_PROJECTS.map((p) => p.slug);

export const NOIDA_PROJECT_COORDINATES = {};
NOIDA_REGISTRY_PROJECTS.forEach((p) => {
  if (typeof p.lat === "number" && typeof p.lng === "number") {
    NOIDA_PROJECT_COORDINATES[p.slug] = {
      lat: p.lat,
      lng: p.lng,
      locality: p.location,
      city: "noida",
      cityName: "Noida",
      propertyType: p.type || "Apartment",
      verified: true,
    };
    NOIDA_PROJECT_COORDINATES[p.id] = NOIDA_PROJECT_COORDINATES[p.slug];
  }
});

function buildAmenitiesForNoida(features = []) {
  return (features || []).map((feat) => {
    const fLower = String(feat).toLowerCase();
    let cat = "Lifestyle";
    let icon = "Sparkles";
    if (fLower.includes("pool") || fLower.includes("gym") || fLower.includes("fitness") || fLower.includes("yoga") || fLower.includes("jogging") || fLower.includes("spa")) {
      cat = "Wellness"; icon = "Dumbbell";
    } else if (fLower.includes("security") || fLower.includes("cctv") || fLower.includes("intercom") || fLower.includes("gated") || fLower.includes("fire")) {
      cat = "Security"; icon = "Shield";
    } else if (fLower.includes("club") || fLower.includes("hall") || fLower.includes("theatre") || fLower.includes("lounge") || fLower.includes("party")) {
      cat = "Social"; icon = "Coffee";
    } else if (fLower.includes("garden") || fLower.includes("tree") || fLower.includes("ev") || fLower.includes("rain") || fLower.includes("solar") || fLower.includes("park")) {
      cat = "Eco"; icon = "Zap";
    } else if (fLower.includes("court") || fLower.includes("sport") || fLower.includes("track") || fLower.includes("cricket") || fLower.includes("badminton")) {
      cat = "Sports"; icon = "Trophy";
    }
    return { name: feat, category: cat, icon };
  });
}

function buildConfigurationsForNoidaProject(p) {
  const extras = NOIDA_REGISTRY_EXTRAS[p.slug] || {};
  const plans = [];

  if (Array.isArray(extras.unitPlan) && extras.unitPlan.length > 0) {
    extras.unitPlan.forEach((grp) => {
      const units = Array.isArray(grp.data) ? grp.data : [];
      units.forEach((u, idx) => {
        const carpet = u.carpet_area ? `${u.carpet_area} sq.ft.` : (p.carpetArea !== "On Request" ? p.carpetArea : "On Request");
        const builtUp = u.built_up_area ? `${u.built_up_area} sq.ft.` : (p.builtUpArea !== "On Request" ? p.builtUpArea : carpet);
        const rawPrice = u.price ? String(u.price).replace(/^₹\s*/i, "").trim() : p.price;
        const imgUrl = u.two_d_url || u.three_d_url || p.images?.[0] || "/images/placeholder-property.jpg";
        plans.push({
          type: grp.label || u.flat_type || p.flatTypes,
          bhk: grp.label || u.flat_type || p.flatTypes,
          carpetArea: carpet,
          superArea: builtUp,
          area: builtUp !== "On Request" ? builtUp : carpet,
          price: rawPrice ? (rawPrice === "On Request" ? "On Request" : `₹ ${rawPrice}`) : (p.price === "On Request" ? "On Request" : `₹ ${p.price}`),
          specs: {
            bedrooms: parseInt(String(grp.label || u.flat_type || ""), 10) || 2,
            bathrooms: parseInt(String(grp.label || u.flat_type || ""), 10) || 2,
            balconies: 1,
            parking: "Covered Parking",
          },
          facing: "East / North Facing",
          description: `Verified configuration at ${p.name}, ${p.location}.`,
          propertyType: u.property_type || p.type || "Apartment",
          image: imgUrl,
          layoutImage: imgUrl,
          key: `${p.id}-${grp.label || "unit"}-${u.id || idx}`,
        });
      });
    });
  }

  if (plans.length === 0 && Array.isArray(extras.configurationSummary) && extras.configurationSummary.length > 0) {
    extras.configurationSummary.forEach((c, idx) => {
      const areaVal = c.carpet_area || (p.carpetArea !== "On Request" ? p.carpetArea : (p.builtUpArea || "On Request"));
      const rawPrice = c.price ? String(c.price).replace(/^₹\s*/i, "").trim() : p.price;
      const imgUrl = p.images?.[0] || "/images/placeholder-property.jpg";
      plans.push({
        type: c.flat_type_name || p.flatTypes,
        bhk: c.flat_type_name || p.flatTypes,
        carpetArea: areaVal,
        superArea: p.builtUpArea || areaVal,
        area: areaVal,
        price: rawPrice === "On Request" ? "On Request" : `₹ ${rawPrice}`,
        specs: { bedrooms: 2, bathrooms: 2, balconies: 1, parking: "Covered Parking" },
        facing: "East / North Facing",
        description: `Verified configuration at ${p.name}, ${p.location}.`,
        propertyType: p.type || "Apartment",
        image: imgUrl,
        layoutImage: imgUrl,
        key: `${p.id}-cfg-${idx}`,
      });
    });
  }

  if (plans.length === 0) {
    const areaVal = p.carpetArea !== "On Request" ? p.carpetArea : (p.builtUpArea || "On Request");
    const imgUrl = p.images?.[0] || "/images/placeholder-property.jpg";
    plans.push({
      type: p.flatTypes || p.type || "Residential",
      bhk: p.flatTypes || p.type || "Residential",
      carpetArea: p.carpetArea || "On Request",
      superArea: p.builtUpArea || areaVal,
      area: areaVal,
      price: p.price && p.price !== "On Request" ? `${p.price}` : "On Request",
      specs: { bedrooms: 2, bathrooms: 2, balconies: 1, parking: "Covered Parking" },
      facing: "East / North Facing",
      description: `Verified configuration at ${p.name}, ${p.location}.`,
      propertyType: p.type || "Apartment",
      image: imgUrl,
      layoutImage: imgUrl,
      key: `${p.id}-default`,
    });
  }

  return plans;
}

export function getNoidaProjectBySlug(rawSlug) {
  if (!rawSlug) return null;
  const clean = decodeURIComponent(String(rawSlug)).toLowerCase().trim();
  let p = NOIDA_BY_SLUG.get(clean) || NOIDA_BY_ID.get(clean);
  if (!p) {
    const pidMatch = clean.match(/-pid-(\d+)$/) || clean.match(/-(\d+)$/);
    if (pidMatch) p = NOIDA_BY_ID.get(pidMatch[1]);
  }
  if (!p) return null;

  const extras = NOIDA_REGISTRY_EXTRAS[p.slug] || {};
  const specs = [
    { label: "Configurations", value: p.flatTypes || "On Request" },
    { label: "Carpet Area", value: p.carpetArea || "On Request" },
    { label: "Built-up Area", value: p.builtUpArea || "On Request" },
    { label: "Possession", value: p.possession || "Under Construction" },
    { label: "Project Status", value: p.status || "Under Construction" },
    { label: "Project Area", value: p.projectArea || "On Request" },
    { label: "Average Rate", value: p.avgPrice || "On Request" },
    { label: "UP RERA ID", value: p.rera || "Not Available" },
  ];

  const reraIds = (p.rera_informations && p.rera_informations.length > 0)
    ? p.rera_informations
    : (p.rera && p.rera !== "Not Available"
        ? p.rera.split(",").map((id) => ({ rera_id: id.trim() }))
        : []);

  const sameLocality = NOIDA_REGISTRY_PROJECTS.filter((item) => item.locality === p.locality && item.slug !== p.slug);
  const otherNoida = (sameLocality.length >= 3
    ? sameLocality
    : NOIDA_REGISTRY_PROJECTS.filter((item) => item.slug !== p.slug)
  ).slice(0, 4);

  const landmarks = [
    { name: `${p.locality} Commercial Belt`, distance: "0.8 km", time: "3 mins", type: "Work" },
    { name: "Noida-Greater Noida Expressway", distance: "2.1 km", time: "5 mins", type: "Expressway" },
    { name: "Aqua Line Metro Station", distance: "1.5 km", time: "4 mins", type: "Transit" },
    { name: "Leading Multi-Speciality Hospital", distance: "3.2 km", time: "8 mins", type: "Healthcare" },
    { name: "Renowned International School", distance: "2.4 km", time: "6 mins", type: "Education" },
    { name: "Upcoming Jewar International Airport", distance: "35 km", time: "35 mins", type: "Airport" },
  ];

  return {
    id: p.id,
    slug: p.slug,
    title: p.name,
    name: p.name,
    builder: p.builder,
    builderLogo: p.builderLogo,
    developerSlug: p.developerSlug,
    city: "noida",
    cityName: "Noida",
    region: p.region,
    locality: p.locality,
    location: p.location,
    fullAddress: p.fullAddress,
    lat: p.lat,
    lng: p.lng,
    price: p.price,
    priceRange: p.priceRange,
    priceNumeric: p.priceNumeric,
    avgPrice: p.avgPrice,
    flatTypes: p.flatTypes,
    carpetArea: p.carpetArea,
    builtUpArea: p.builtUpArea,
    projectArea: p.projectArea,
    possession: p.possession,
    possessionStatus: p.possessionStatus,
    status: p.status,
    rera: p.rera,
    rera_informations: reraIds,
    stateReraLink: extras.stateReraLink || "https://up-rera.in/",
    tag: p.tag,
    type: p.type,
    isExclusive: p.isExclusive,
    isRera: p.isRera,
    rating: 4.8,
    reviewsCount: 84,
    images: p.images,
    overview: p.description,
    highlights: [
      `Prime address in ${p.location}`,
      `Developed by ${p.builder}`,
      p.rera && p.rera !== "Not Available" ? `UP RERA Registered: ${p.rera}` : "Verified PropertyPistol Noida Listing",
      `Available Configurations: ${p.flatTypes || p.type}`,
      `Possession: ${p.possession}`,
    ],
    specs,
    amenities: buildAmenitiesForNoida(p.features && p.features.length > 0 ? p.features : ["24x7 Security", "Landscaped Garden", "Car Parking", "Club House"]),
    amenitiesDetails: extras.amenitiesDetails || [],
    floorPlans: buildConfigurationsForNoidaProject(p),
    bankOffers: extras.bankOffers || [],
    landmarks,
    developerInfo: {
      name: p.builder,
      slug: p.developerSlug,
      logo: p.builderLogo,
      description: p.builderDescription || `${p.builder} develops verified residential communities across Noida and Greater Noida.`,
    },
    relatedProjectSlugs: otherNoida.map((o) => o.slug),
    nearbyProjects: otherNoida.map((o) => ({
      id: o.id,
      slug: o.slug,
      name: o.name,
      title: o.name,
      location: o.location,
      price: o.price,
      flatTypes: o.flatTypes,
      images: o.images,
      city: "noida",
    })),
    referenceUrl: p.referenceUrl,
  };
}
